-- Manual move quality preview. HARD permission remains owned by preview_schedule_move_v1/preview_schedule_swap_v1.
create or replace function public.preview_schedule_move_quality_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_classroom_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare h jsonb;p jsonb;b record;a record;after_h numeric:=0;after_m numeric:=0;after_s numeric:=0;ok_after boolean:=false;begin perform public.open_permission_context('schedule.edit');h:=public.preview_schedule_move_v1(p_schedule_id,p_weekday,p_period,p_classroom_id);if not coalesce((h->>'ok')::boolean,false) then return h||jsonb_build_object('quality_available',false);end if;select * into b from public.get_schedule_current_generic_relation_summary_v1();p:=public.get_schedule_atomic_move_plan_v1(p_schedule_id,p_weekday,p_period,p_classroom_id);begin perform public.move_schedule_slots_batch_v1(p->'moves');select * into a from public.get_schedule_current_generic_relation_summary_v1();after_h:=coalesce(a.hard,0);after_m:=coalesce(a.medium,0);after_s:=coalesce(a.soft,0);ok_after:=true;raise exception using errcode='P0001',message='OKULOS_QUALITY_PREVIEW_ROLLBACK';exception when others then if SQLERRM<>'OKULOS_QUALITY_PREVIEW_ROLLBACK' then return h||jsonb_build_object('quality_available',false,'quality_error',SQLERRM);end if;end;if not ok_after then return h||jsonb_build_object('quality_available',false);end if;return h||jsonb_build_object('quality_available',true,'quality_scope','CANONICAL_GENERIC_RELATIONS','quality_direction','NEGATIVE_DELTA_IS_BETTER','relation_hard_before',coalesce(b.hard,0),'relation_hard_after',after_h,'relation_hard_delta',after_h-coalesce(b.hard,0),'medium_before',coalesce(b.medium,0),'medium_after',after_m,'medium_delta',after_m-coalesce(b.medium,0),'soft_before',coalesce(b.soft,0),'soft_after',after_s,'soft_delta',after_s-coalesce(b.soft,0));end$$;
create or replace function public.preview_schedule_swap_quality_v1(p_left_id uuid,p_right_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare h jsonb;a0 public.teacher_schedule%rowtype;b0 public.teacher_schedule%rowtype;lp jsonb;rp jsonb;moves jsonb;b record;a record;after_h numeric:=0;after_m numeric:=0;after_s numeric:=0;ok_after boolean:=false;begin perform public.open_permission_context('schedule.edit');h:=public.preview_schedule_swap_v1(p_left_id,p_right_id);if not coalesce((h->>'ok')::boolean,false) then return h||jsonb_build_object('quality_available',false);end if;select * into a0 from public.teacher_schedule where id=p_left_id and active and institution_code=public.current_tenant_code();select * into b0 from public.teacher_schedule where id=p_right_id and active and institution_code=public.current_tenant_code();if a0.id is null or b0.id is null then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_NOT_FOUND','quality_available',false);end if;lp:=public.get_schedule_atomic_move_plan_v1(a0.id,b0.weekday,b0.period,a0.classroom_id);rp:=public.get_schedule_atomic_move_plan_v1(b0.id,a0.weekday,a0.period,b0.classroom_id);moves:=(lp->'moves')||(rp->'moves');select * into b from public.get_schedule_current_generic_relation_summary_v1();begin perform public.move_schedule_slots_batch_v1(moves);select * into a from public.get_schedule_current_generic_relation_summary_v1();after_h:=coalesce(a.hard,0);after_m:=coalesce(a.medium,0);after_s:=coalesce(a.soft,0);ok_after:=true;raise exception using errcode='P0001',message='OKULOS_QUALITY_PREVIEW_ROLLBACK';exception when others then if SQLERRM<>'OKULOS_QUALITY_PREVIEW_ROLLBACK' then return h||jsonb_build_object('quality_available',false,'quality_error',SQLERRM);end if;end;if not ok_after then return h||jsonb_build_object('quality_available',false);end if;return h||jsonb_build_object('quality_available',true,'quality_scope','CANONICAL_GENERIC_RELATIONS','quality_direction','NEGATIVE_DELTA_IS_BETTER','relation_hard_before',coalesce(b.hard,0),'relation_hard_after',after_h,'relation_hard_delta',after_h-coalesce(b.hard,0),'medium_before',coalesce(b.medium,0),'medium_after',after_m,'medium_delta',after_m-coalesce(b.medium,0),'soft_before',coalesce(b.soft,0),'soft_after',after_s,'soft_delta',after_s-coalesce(b.soft,0));end$$;
revoke all on function public.preview_schedule_move_quality_v1(uuid,smallint,smallint,uuid) from public;grant execute on function public.preview_schedule_move_quality_v1(uuid,smallint,smallint,uuid) to authenticated;revoke all on function public.preview_schedule_swap_quality_v1(uuid,uuid) from public;grant execute on function public.preview_schedule_swap_quality_v1(uuid,uuid) to authenticated;
